pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 probe) internal {
        vm.assume(probe >= 0);
        uint balBefore = address(c).balance;
        vm.assume(balBefore == 0);
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        try c.withdrawAll() {} catch { return; }
        assertTrue(address(c).balance == balBefore && c.depositsCount() == countBefore);
    }

    function testFuzz_run(uint256 probe) public {
        _run(probe);
    }

    receive() external payable {}
}
